+import { injectForPath } from "./core/inject.ts";
+
+// Direct CLI for tools without hook support
+// Usage: node cli.js <repo> <file-path>
+// Output: injected context as string, or nothing if no records
+
+const [, , repo, filePath] = process.argv;
+
+if (!repo || !filePath) {
+  process.stderr.write("Usage: cli.js <repo> <file-path>\n");
+  process.exit(1);
+}
+
+const result = injectForPath(repo, filePath);
+if (result) {
+  process.stdout.write(result);
+}
