+++ b/src/core/context.ts
@@ -0,0 +1,18 @@
+// Global context for tracking the current operation
+let currentRepo: string | null = null;
+let currentFilePath: string | null = null;
+
+export const setContext = (repo: string, filePath: string): void => {
+  currentRepo = repo;
+  currentFilePath = filePath;
+};
+
+export const clearContext = (): void => {
+  currentRepo = null;
+  currentFilePath = null;
+};
+
+export const getContext = (): { repo: string; filePath: string } | null => {
+  if (!currentRepo || !currentFilePath) return null;
+  return { repo: currentRepo, filePath: currentFilePath };
+};
