@@ -0,0 +1,12 @@
+import { setContext } from "./context.ts";
+
+// Check environment variables set by the calling environment
+// Tools can read these without any hook support
+export const initFromEnvironment = (): void => {
+  const repo = process.env.COMMITLORE_REPO;
+  const filePath = process.env.COMMITLORE_FILE;
+
+  if (repo && filePath) {
+    setContext(repo, filePath);
+  }
+};
diff --git a/src/core/tool-injection.ts b/src/core/tool-injection.ts
