--- /dev/null
+++ b/src/core/tool-injection.ts
@@ -0,0 +1,12 @@
+import { injectForPath } from "./inject.ts";
+import { getContext, clearContext } from "./context.ts";
+
+// Tools call this to retrieve records for the current operation
+export const getInjectedContext = (): string | null => {
+  const context = getContext();
+  if (!context) return null;
+
+  const injected = injectForPath(context.repo, context.filePath);
+  clearContext(); // Clean up after injection
+  return injected;
+};
